-- Recovered from the production migration ledger for deterministic rebuilds.
alter table public.v2_groups add column if not exists university text; alter table public.v2_groups add column if not exists program text; alter table public.v2_groups add column if not exists group_name text; alter table public.v2_groups add column if not exists school_cycle text; update public.v2_groups g set group_name=coalesce(g.group_name,g.name), school_cycle=coalesce(g.school_cycle,g.term), program=coalesce(g.program,p.name), university=coalesce(g.university,u.name) from public.v2_programs p left join public.v2_universities u on u.id=p.university_id where g.program_id=p.id; update public.v2_groups set group_name=coalesce(group_name,name), school_cycle=coalesce(school_cycle,term) where group_name is null or school_cycle is null;

